WITH with_windows AS (SELECT id, store_id, quantity, LAST_VALUE(quantity) IGNORE NULLS OVER (PARTITION BY store_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity, LEAD(quantity, 1) OVER (PARTITION BY store_id ORDER BY quantity, id) AS next_quantity, LEAD(quantity, 1) OVER (PARTITION BY product_id ORDER BY last_restock, id) AS next_quantity_2 FROM inventory) SELECT id, store_id, quantity, last_known_quantity, next_quantity FROM with_windows ORDER BY quantity DESC NULLS FIRST
